"""Validate provenance for hypothesis records; this does not judge strategic truth."""
from __future__ import annotations

import json
from pathlib import Path

from .index import CLASSES, connect, dumps, manifest_of, sha


def save_hypotheses(index,retrieval_dir,report,destination):
    retrieval_dir=Path(retrieval_dir)
    retrieval=json.loads((retrieval_dir/"retrieval.json").read_text())
    db=connect(index)
    manifest=manifest_of(db)
    if report.get("replay_sha256")!=manifest["replay_sha256"] or retrieval["replay_sha256"]!=manifest["replay_sha256"]:
        raise ValueError("Hypothesis/retrieval belongs to a different replay")
    if report.get("retrieval_id")!=retrieval["retrieval_id"]:
        raise ValueError("Retrieval ID mismatch")
    returned={json.loads(line)["evidence_id"] for line in (retrieval_dir/"operations.jsonl").open()}
    for hypothesis in report["hypotheses"]:
        if hypothesis["status"] not in {"proposed","supported","rejected","inconclusive"}:
            raise ValueError("Unknown hypothesis status")
        if hypothesis["status"]=="supported" and hypothesis.get("blocking_unknowns"):
            raise ValueError("Supported hypothesis has unresolved blocking unknowns")
        for field in ("evidence_for","counterevidence","adversarial_checks","strategic_conclusions"):
            for claim in hypothesis.get(field,[]):
                if claim.get("classification") not in CLASSES:
                    raise ValueError("Every claim needs an evidence classification")
                refs=claim.get("evidence_refs",[])
                if claim["classification"] in {"raw/decoded observation","decoded telemetry","deterministic reconstruction"} and not refs:
                    raise ValueError("Observation/reconstruction claim has no evidence references")
                if claim.get("confidence") not in {"high","medium","low","unresolved"}:
                    raise ValueError("Every claim needs confidence")
                for ref in refs:
                    if ref not in returned:
                        raise ValueError("Claim references evidence not returned by this retrieval")
                    if db.execute("SELECT 1 FROM operations WHERE evidence_id=?",(ref,)).fetchone() is None:
                        raise ValueError("Evidence reference is absent from index")
                if field=="strategic_conclusions" and claim["classification"]!="strategic inference":
                    raise ValueError("Strategic conclusions require their own classification")
                if field=="strategic_conclusions" and claim.get("verdict_scope")=="final" and hypothesis["status"]!="supported":
                    raise ValueError("Inconclusive hypothesis cannot produce a final strategic verdict")
    db.close()
    saved=dict(report, schema_version=1,validator="hypothesis-provenance/0.1",
               validation_scope="classification, declared status and reference membership; no automated truth check",
               observation_manifest_ref="manifest.json",
               corpus_usage="No expert-corpus principle applied to establish match facts")
    saved["report_revision_id"]=sha(dumps(saved).encode())
    destination=Path(destination)
    if destination.exists():
        raise FileExistsError("Hypothesis revision already exists")
    destination.write_text(json.dumps(saved,indent=2))
    return saved

