"""Load pre-generated, versioned strategic reports. No model or parser calls."""
from __future__ import annotations

import hashlib
import json
import logging
import math
import re
from datetime import datetime
from pathlib import Path

from .publish import atomic_write

LOG = logging.getLogger(__name__)
MAX_REPORT_BYTES = 512_000
CLASSES = {"raw/decoded observation", "decoded telemetry", "deterministic reconstruction",
           "heuristic inference", "strategic inference", "human-supplied context"}
CONFIDENCE = {"high", "medium", "low", "unresolved"}
SHA256 = re.compile(r"[0-9a-f]{64}\Z")


def _integer(value, name, minimum=0):
    if type(value) is not int or value < minimum:
        raise ValueError(f"{name} must be an integer >= {minimum}")
    return value


def _text(value, name, limit=4000):
    if not isinstance(value, str) or not value.strip() or len(value) > limit:
        raise ValueError(f"Invalid {name}")
    return value


def _list(value, name, limit=100):
    if not isinstance(value, list) or len(value) > limit:
        raise ValueError(f"Invalid {name}")
    return value


def _object(value, name):
    if not isinstance(value, dict):
        raise ValueError(f"Invalid {name}")
    return value


def _hash(value, name):
    if not isinstance(value, str) or not SHA256.fullmatch(value):
        raise ValueError(f"Invalid {name}")


def _read(path):
    return parse_report_json(path.read_bytes())


def parse_report_json(raw):
    if len(raw) > MAX_REPORT_BYTES:
        raise ValueError("Report exceeds the publication budget; retain full evidence in the index")
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError(f"Duplicate JSON key: {key}")
            result[key] = value
        return result
    def constant(value):
        raise ValueError(f"Non-finite JSON number: {value}")
    return json.loads(raw, object_pairs_hook=pairs, parse_constant=constant)


def validate_report(report, match_id, revision):
    """Validate the publication contract and reference closure, not strategic truth."""
    _object(report, "report")
    if _integer(report.get("schema_version"), "schema_version", 1) != 1:
        raise ValueError("Unsupported strategic-report schema")
    if _integer(report.get("match_id"), "match_id", 1) != match_id:
        raise ValueError("Report belongs to a different match")
    if _integer(report.get("revision"), "revision", 1) != revision:
        raise ValueError("Revision does not match its filename")
    if report.get("kind") not in {"evidence_review", "strategic_recap"}:
        raise ValueError("Unknown report kind")
    if report.get("status") not in {"draft", "reviewed"}:
        raise ValueError("Unknown report status")
    if report.get("confidence") not in CONFIDENCE:
        raise ValueError("Unknown confidence")
    date = datetime.fromisoformat(_text(report.get("created_at"), "created_at", 80).replace("Z", "+00:00"))
    if date.tzinfo is None:
        raise ValueError("Report creation timestamp needs a timezone")
    _text(report.get("author"), "author", 160)
    _text(report.get("headline"), "headline", 240)
    _text(report.get("summary"), "summary", 1800)
    provenance = _object(report.get("provenance"), "provenance")
    _hash(provenance.get("replay_sha256"), "replay_sha256")
    _hash(provenance.get("retrieval_id"), "retrieval_id")
    _hash(provenance.get("source_report_revision_id"), "source_report_revision_id")
    duration = _integer(provenance.get("duration_ms"), "duration_ms", 1)
    size = _integer(provenance.get("replay_byte_length"), "replay_byte_length", 1)
    if type(provenance.get("body_byte_coverage_complete")) is not bool:
        raise ValueError("Coverage must be explicit")
    for name in ("index_operation_count", "retrieved_operation_count"):
        _integer(provenance.get(name), name, 1)
    window = _object(provenance.get("retrieved_window"), "retrieved_window")
    start = _integer(window.get("start_ms"), "window start")
    end = _integer(window.get("end_ms"), "window end")
    if not start <= end <= duration:
        raise ValueError("Invalid retrieval span")
    roster = _list(report.get("players"), "players", 8)
    slots = set()
    for player in roster:
        _object(player, "player")
        slot = _integer(player.get("player_id"), "player_id", 1)
        if slot > 8 or slot in slots:
            raise ValueError("Duplicate or invalid player slot")
        slots.add(slot)
        _text(player.get("name"), "player name", 160)
        if player.get("profile_id") is not None:
            _integer(player["profile_id"], "profile_id", 1)
        if player.get("classification") != "raw/decoded observation":
            raise ValueError("Roster needs its observation classification")
    if not roster:
        raise ValueError("Report has no player identities")
    evidence = _list(report.get("evidence"), "evidence", 200)
    refs = set()
    for event in evidence:
        _object(event, "evidence event")
        ordinal = _integer(event.get("ordinal"), "operation ordinal")
        expected = f"{provenance['replay_sha256']}:op:{ordinal}"
        if event.get("evidence_id") != expected or expected in refs:
            raise ValueError("Invalid, duplicate or cross-replay evidence reference")
        refs.add(expected)
        stamp = _integer(event.get("time_ms"), "evidence timestamp")
        if not start <= stamp <= end:
            raise ValueError("Evidence lies outside declared retrieved span")
        if event.get("classification") not in CLASSES:
            raise ValueError("Unclassified evidence")
        if event.get("player_id") is not None and event["player_id"] not in slots:
            raise ValueError("Evidence actor is absent from roster")
        offset = _integer(event.get("byte_offset"), "byte_offset")
        length = _integer(event.get("byte_length"), "byte_length", 1)
        if offset + length > size:
            raise ValueError("Evidence byte span is outside the recording")
        _object(event.get("payload"), "operation payload")
        for coordinate in ("x", "y"):
            value = event.get(coordinate)
            if value is not None and (type(value) not in (int, float) or not math.isfinite(value)):
                raise ValueError("Invalid evidence coordinates")
        if event.get("action") is not None:
            _text(event["action"], "action name", 80)
        for object_id in _list(event["payload"].get("object_ids", []), "selected object IDs", 1000):
            _integer(object_id, "selected object ID")
        _text(event.get("kind"), "operation kind", 40)
        if "raw_bytes_hex" in event:
            hex_value = _text(event["raw_bytes_hex"], "operation bytes", 128_000)
            if len(bytes.fromhex(hex_value)) != length:
                raise ValueError("Evidence bytes disagree with byte span")
    if provenance["retrieved_operation_count"] < len(evidence):
        raise ValueError("Published evidence exceeds declared retrieval")
    def claim(value):
        _object(value, "claim")
        _text(value.get("text"), "claim text")
        if value.get("classification") not in CLASSES or value.get("confidence") not in CONFIDENCE:
            raise ValueError("Claim needs classification and confidence")
        cited = _list(value.get("evidence_refs"), "claim references", 200)
        if any(not isinstance(ref, str) or ref not in refs for ref in cited):
            raise ValueError("Unresolved claim evidence reference")
        if value["classification"] in {"raw/decoded observation", "decoded telemetry", "deterministic reconstruction"} and not cited:
            raise ValueError("Observed/reconstructed claim has no evidence")
    if report.get("opening_contract") is not None:
        claim(report["opening_contract"])
    for point in _list(report.get("turning_points"), "turning_points", 8):
        claim(point)
        _text(point.get("title"), "point title", 200)
        if _integer(point.get("time_ms"), "point timestamp") > duration:
            raise ValueError("Turning point exceeds recording duration")
    for name in ("what_went_well", "what_to_improve", "next_game_rules"):
        for item in _list(report.get(name), name, 8):
            claim(item)
    for item in _list(report.get("uncertainties"), "uncertainties", 16):
        _text(item, "uncertainty", 1000)
    for context in _list(report.get("human_context_used"), "human_context_used", 50):
        claim(context)
        if context["classification"] != "human-supplied context":
            raise ValueError("Human context must retain its classification")
        _text(context.get("author"), "context author", 160)
    return report


def load_strategy(match_id, directory, context, replay_dir):
    """A malformed or stale report never prevents ordinary match-page generation."""
    folder = Path(directory) / str(match_id)
    pointer = folder / "current.json"
    if not pointer.exists():
        return None
    try:
        current = _object(_read(pointer), "current pointer")
        if _integer(current.get("schema_version"), "pointer schema", 1) != 1:
            raise ValueError("Unsupported pointer schema")
        revision = _integer(current.get("revision"), "pointer revision", 1)
        report = validate_report(_read(folder / f"v{revision}.json"), match_id, revision)
        duration = context.get("analysis_duration_ms")
        if duration is not None and duration != report["provenance"]["duration_ms"]:
            raise ValueError("Report's replay clock differs from the metrics recording")
        profiles = {p.get("profile_id") for p in report["players"] if p.get("profile_id") is not None}
        if any(p.get("profile_id") is not None and p["profile_id"] not in profiles for p in context.get("players", [])):
            raise ValueError("Stored match players differ from the report roster")
        replay = Path(replay_dir) / f"M_{match_id}.aoe2record"
        verified = False
        if replay.is_file():
            if hashlib.sha256(replay.read_bytes()).hexdigest() != report["provenance"]["replay_sha256"]:
                raise ValueError("Report refers to a different recording than the site's download")
            verified = True
        revisions = []
        for path in sorted(folder.glob("v*.json")):
            filename = re.fullmatch(r"v([1-9][0-9]*)\.json", path.name)
            if not filename:
                continue
            number = int(filename[1])
            # Future, not-yet-selected drafts are not published by this pointer.
            if number > revision:
                continue
            try:
                revisions.append(validate_report(_read(path), match_id, number))
            except (OSError, ValueError, TypeError) as exc:
                LOG.warning("Skipping invalid strategy history %s: %s", path, exc)
        revisions.sort(key=lambda r: r["revision"])
        return dict(report=report, revisions=revisions, replay_verified=verified)
    except (OSError, ValueError, TypeError, KeyError) as exc:
        LOG.warning("Skipping strategy report for match %s: %s", match_id, exc)
        return None


def publish_strategy(site_dir, bundle):
    report = bundle["report"]
    destination = Path(site_dir) / "strategy" / str(report["match_id"])
    for revision in bundle["revisions"]:
        path = destination / f"v{revision['revision']}.json"
        if path.exists() and _read(path) != revision:
            raise ValueError(f"Published strategy revision is immutable: {path.name}")
        if not path.exists():
            atomic_write(path, (json.dumps(revision, ensure_ascii=False, indent=2, allow_nan=False) + "\n").encode())
    atomic_write(destination / "current.json", (json.dumps({"schema_version": 1, "revision": report["revision"]}) + "\n").encode())
